def transform(grid):
    n, m = len(grid), len(grid[0])
    flat = [v for row in grid for v in row]
    bg = max(set(flat), key=flat.count)
    mid = [grid[r][c] for r in range(max(0,n//2-3),min(n,n//2+4))
           for c in range(max(0,m//2-3),min(m,m//2+4)) if grid[r][c] != bg]
    line = max(set(mid), key=mid.count)
    others = sorted(set(flat)-{bg,line})
    out = [row[:] for row in grid]
    if len(others) != 2:
        return out

    # Dominant marker colours on the two sides provide positional fallbacks.
    counts=[{},{}]
    for r in range(n):
        for c in range(m):
            v=grid[r][c]
            if v in others:
                d=counts[0 if c<m//2 else 1]
                d[v]=d.get(v,0)+1
    fallback=[max(d,key=d.get) for d in counts]

    # Connected components of maze pixels. A component touching a marker patch
    # takes that patch's colour; the detached central symbol is retained.
    comps=[]
    seen=set()
    for r in range(n):
        for c in range(m):
            if grid[r][c]!=line or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]; adjacent={}
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<n and 0<=b<m:
                        v=grid[a][b]
                        if v==line and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
                        elif v in others:
                            adjacent[v]=adjacent.get(v,0)+1
            comps.append((comp,adjacent))

    central=None
    detached=[(sum(abs(x-(n-1)/2)+abs(y-(m-1)/2) for x,y in comp)/len(comp),i)
              for i,(comp,adj) in enumerate(comps) if not adj and len(comp)>=5]
    if detached:
        central=min(detached)[1]

    for i,(comp,adj) in enumerate(comps):
        if i==central:
            continue
        if adj:
            colour=max(adj,key=adj.get)
        else:
            colour=fallback[0] if sum(c for r,c in comp)/len(comp)<m//2 else fallback[1]
        for r,c in comp:
            out[r][c]=colour
    return out
